import { useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { ArrowRight, Check, ChevronDown, ChevronLeft, ClipboardCheck, ExternalLink, FileText, Globe2, Info, Landmark, Link as LinkIcon, Mail, MapPin, Menu, Phone, Plus, Search, ShieldCheck, SlidersHorizontal, Sparkles, Stethoscope, X } from 'lucide-react';
import { Link, Route, Switch, Router as WouterRouter, useLocation, useParams } from 'wouter';
import {
  getGetAdminSummaryQueryKey,
  getGetClinicQueryKey,
  getListAdminClinicsQueryKey,
  getListAuditEventsQueryKey,
  getListClinicsQueryKey,
  getListLocationsQueryKey,
  getListRateObservationsQueryKey,
  getListServicesQueryKey,
  getListSourcesQueryKey,
  useArchiveClinic,
  useCreateClinic,
  useCreateRateObservation,
  useCreateService,
  useCreateSource,
  useGetAdminSummary,
  useGetClinic,
  useListAdminClinics,
  useListAuditEvents,
  useListClinics,
  useListLocations,
  useListRateObservations,
  useListServices,
  useListSources,
  usePreviewImport,
  usePublishRateObservation,
  useSubmitCorrection,
  useUnpublishRateObservation,
  useUpdateClinic,
} from '@workspace/api-client-react';
import type { Clinic, ClinicProfile, Location, RateObservation, Service } from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';
import './index.css';

const queryClient = new QueryClient();

const navItems = [
  { href: '/clinics', label: 'Find a clinic' },
  { href: '/locations', label: 'Locations' },
  { href: '/methodology', label: 'Methodology' },
  { href: '/glossary', label: 'Glossary' },
];

function Button({ children, variant = 'primary', className = '', ...props }: { children: React.ReactNode; variant?: 'primary' | 'quiet' | 'outline' | 'danger'; className?: string; [key: string]: unknown }) {
  return <button className={`btn btn-${variant} ${className}`} {...props}>{children}</button>;
}

function Logo() {
  return <Link href="/" className="brand" data-testid="link-home"><span className="brand-mark"><span /></span><span>clear<span className="brand-light">care</span></span></Link>;
}

function Shell({ children }: { children: React.ReactNode }) {
  const [menuOpen, setMenuOpen] = useState(false);
  return <div className="app-shell">
    <header className="site-header">
      <div className="shell-inner header-inner">
        <Logo />
        <nav className="desktop-nav" aria-label="Primary navigation">{navItems.map(item => <Link key={item.href} href={item.href} className="nav-link" data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}>{item.label}</Link>)}</nav>
        <div className="header-actions">
          <Link href="/about" className="header-about" data-testid="link-about">About this directory</Link>
          <Link href="/admin" className="admin-link" data-testid="link-admin">Editor access</Link>
          <Button variant="quiet" className="menu-button" onClick={() => setMenuOpen(!menuOpen)} aria-label="Open navigation menu" data-testid="button-menu"><Menu size={20} /></Button>
        </div>
      </div>
      {menuOpen && <nav className="mobile-nav shell-inner" aria-label="Mobile navigation">{navItems.concat([{ href: '/about', label: 'About' }]).map(item => <Link key={item.href} href={item.href} onClick={() => setMenuOpen(false)} className="mobile-nav-link" data-testid={`mobile-link-${item.label.toLowerCase().replaceAll(' ', '-')}`}>{item.label}<ArrowRight size={16} /></Link>)}</nav>}
    </header>
    <main>{children}</main>
    <Footer />
  </div>;
}

function Footer() {
  return <footer className="site-footer"><div className="shell-inner footer-grid">
    <div><Logo /><p className="footer-note">A public reference for understanding IVF clinic information in India.</p></div>
    <div><p className="footer-heading">Explore</p>{navItems.slice(0, 2).map(i => <Link key={i.href} href={i.href} className="footer-link" data-testid={`footer-link-${i.label.toLowerCase().replaceAll(' ', '-')}`}>{i.label}</Link>)}</div>
    <div><p className="footer-heading">Read first</p><Link href="/methodology" className="footer-link" data-testid="footer-link-methodology">How we show rates</Link><Link href="/glossary" className="footer-link" data-testid="footer-link-glossary">Terms, in plain language</Link></div>
    <div><p className="footer-heading">Project</p><Link href="/about" className="footer-link" data-testid="footer-link-about">About</Link><Link href="/corrections" className="footer-link" data-testid="footer-link-corrections">Suggest a correction</Link><Link href="/privacy" className="footer-link" data-testid="footer-link-privacy">Privacy</Link><Link href="/terms" className="footer-link" data-testid="footer-link-terms">Terms</Link></div>
  </div><div className="shell-inner footer-bottom"><span>Demonstration directory · India</span><span>Information, not medical advice.</span></div></footer>;
}

function Eyebrow({ children }: { children: React.ReactNode }) { return <p className="eyebrow">{children}</p>; }
function PageIntro({ eyebrow, title, description }: { eyebrow: string; title: string; description?: string }) { return <section className="page-intro shell-inner"><Eyebrow>{eyebrow}</Eyebrow><h1>{title}</h1>{description && <p className="intro-copy">{description}</p>}</section>; }
function Disclaimer({ compact = false }: { compact?: boolean }) { return <div className={`disclaimer ${compact ? 'disclaimer-compact' : ''}`}><Info size={17} /><span><strong>Medical information note.</strong> Clinic-level statistics describe groups of past treatment cycles. They do not predict an individual patient’s outcome. Rates calculated using different outcomes, denominators, patient groups, or treatment methods may not be comparable. This directory provides general information and not medical advice.</span></div>; }
function LoadingBlock({ lines = 3 }: { lines?: number }) { return <div className="loading-block" aria-label="Loading"><span className="skeleton skeleton-title" />{Array.from({ length: lines }).map((_, i) => <span key={i} className="skeleton" />)}</div>; }
function ErrorBlock({ retry }: { retry: () => void }) { return <div className="state-card"><p className="eyebrow">Could not load this view</p><h2>Something interrupted the connection.</h2><p>Try again, or come back in a moment.</p><Button variant="outline" onClick={retry} data-testid="button-retry">Retry</Button></div>; }
function EmptyBlock({ title, body }: { title: string; body: string }) { return <div className="empty-state"><div className="empty-icon"><Search size={20} /></div><h3>{title}</h3><p>{body}</p></div>; }

function RateDefinition({ observation, expanded = false }: { observation: RateObservation; expanded?: boolean }) {
  const [open, setOpen] = useState(expanded);
  return <div className={`rate-card ${open ? 'rate-open' : ''}`} data-testid={`rate-observation-${observation.id}`}>
    <div className="rate-top"><div><p className="rate-label">{observation.outcomeType}</p><p className="rate-definition">{observation.outcomeDefinition}</p></div><div className="rate-value">{observation.ratePercentage.toFixed(1)}<span>%</span></div></div>
    <div className="rate-context"><span>{observation.denominatorType}</span><span>{observation.ageBand}</span><span>{observation.eggSource}</span><span>{observation.treatmentContext}</span><span>{observation.yearLabel}</span><span className="source-badge">{observation.source.sourceType}</span><span className="verification-badge">{observation.verificationStatus}</span>{observation.smallSample && <span className="caveat">Small sample</span>}</div>
    {open && <div className="rate-detail"><div><span className="detail-label">Denominator</span><strong>{observation.denominatorType}</strong><p>{observation.denominatorDefinition}{observation.denominatorCount ? ` · ${observation.denominatorCount} people` : ''}{observation.numerator !== null && observation.numerator !== undefined ? ` · ${observation.numerator} events` : ''}</p></div><div><span className="detail-label">Context</span><strong>{observation.treatmentContext}</strong><p>Egg source: {observation.eggSource}. {observation.ageMeasurementPoint || 'Age at treatment start.'}</p></div><div><span className="detail-label">Reporting period</span><strong>{observation.reportingPeriodStart} — {observation.reportingPeriodEnd}</strong><p>{observation.methodologyNotes}</p></div><div className="source-inline"><FileText size={15} /><span>Source: {observation.source.title}</span></div></div>}
    {open && <div className="rate-detail"><div><span className="detail-label">Denominator</span><strong>{observation.denominatorType}</strong><p>{observation.denominatorDefinition}{observation.denominatorCount !== null && observation.denominatorCount !== undefined ? ` · ${observation.denominatorCount} in denominator` : ' · Sample size not reported'}{observation.numerator !== null && observation.numerator !== undefined ? ` · ${observation.numerator} events` : ''}</p></div><div><span className="detail-label">Context</span><strong>{observation.treatmentType} · {observation.treatmentContext}</strong><p>Egg source: {observation.eggSource}. {observation.ageMeasurementPoint || 'Age at treatment start.'}</p></div><div><span className="detail-label">Reporting period</span><strong>{observation.reportingPeriodStart} — {observation.reportingPeriodEnd}</strong><p>{observation.methodologyNotes}</p></div></div>}
    <div className="rate-source"><FileText size={15} /><a href={observation.source.url} target="_blank" rel="noreferrer">View direct source</a><span>{observation.source.title}</span></div>
    <button className="rate-toggle" onClick={() => setOpen(!open)} aria-expanded={open} data-testid={`button-rate-details-${observation.id}`}>{open ? 'Hide context' : 'See the definition and context'}<ChevronDown size={15} className={open ? 'rotate-180' : ''} /></button>
  </div>;
}

function ClinicCard({ clinic }: { clinic: Clinic }) {
  return <article className="clinic-card" data-testid={`card-clinic-${clinic.id}`}>
    <div className="clinic-card-top"><div><span className="status-dot" /> <span className="micro-label">{clinic.licensingStatus || 'Licensing information available'}</span></div><span className="reviewed">{clinic.demonstrationData ? 'Demonstration record' : `Reviewed ${new Date(clinic.lastReviewedAt).toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}`}</span></div>
    <Link href={`/clinics/${clinic.slug}`} className="clinic-card-title" data-testid={`link-clinic-${clinic.id}`}>{clinic.name}<ArrowRight size={18} /></Link>
    <p className="clinic-location"><MapPin size={15} />{clinic.city}, {clinic.state}</p>
    {clinic.headlineObservation ? <RateDefinition observation={clinic.headlineObservation} /> : <p className="no-rate">No eligible rate observation is published for this record.</p>}
    <div className="service-row">{clinic.services.slice(0, 3).map(service => <span key={service.id}>{service.name}</span>)}</div>
  </article>;
}

function Home() {
  const [, setLocation] = useLocation();
  const [query, setQuery] = useState('');
  const locationsQuery = useListLocations({ query: { queryKey: getListLocationsQueryKey() } });
  const locations = locationsQuery.data ?? [];
  const submit = (event: React.FormEvent) => { event.preventDefault(); setLocation(`/clinics${query.trim() ? `?q=${encodeURIComponent(query.trim())}` : ''}`); };
  return <Shell><section className="hero"><div className="shell-inner hero-grid"><div className="hero-copy"><Eyebrow>India IVF clinic directory</Eyebrow><h1>Make a considered <em>choice.</em></h1><p className="hero-lede">A clearer way to compare clinic information — with the definition behind every number.</p><form className="search-box" onSubmit={submit}><Search size={20} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search by clinic, city or state" aria-label="Search by clinic, city or state" data-testid="input-home-search" /><button type="submit" data-testid="button-home-search"><ArrowRight size={20} /></button></form><p className="hero-helper">Start with a location, then read the context.</p></div><div className="hero-art" aria-label="A layered illustration of a reference card"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="art-card art-card-back"><span>reported period</span><b>2022—23</b></div><div className="art-card art-card-main"><div className="art-card-header"><span className="status-dot" /><span>OBSERVATION / 04</span></div><strong>Live birth rate</strong><span className="art-number">31.4<small>%</small></span><div className="art-rule" /><p>per embryo transfer<br />age 35–37 · own eggs</p></div><div className="art-caption"><span className="caption-line" />Information with its edges intact.</div></div></div></section><section className="trust-strip"><div className="shell-inner trust-grid"><div><ShieldCheck size={20} /><strong>Evidence-led, not outcome-ranked</strong></div><div><ClipboardCheck size={20} /><strong>Definitions stay next to rates</strong></div><div><Globe2 size={20} /><strong>Built for India, in plain language</strong></div></div></section><section className="home-section shell-inner"><div className="section-heading"><div><Eyebrow>Begin nearby</Eyebrow><h2>Browse by location</h2></div><Link href="/locations" className="text-link" data-testid="link-home-locations">See all locations <ArrowRight size={16} /></Link></div><div className="location-grid home-locations">{locationsQuery.isLoading ? <LoadingBlock lines={2} /> : locations.slice(0, 6).map((location: Location) => <Link key={location.slug} href={`/clinics?location=${location.slug}`} className="location-tile" data-testid={`link-home-location-${location.slug}`}><span className="location-name">{location.city}</span><span>{location.state}</span><span className="location-count">{location.clinicCount} {location.clinicCount === 1 ? 'clinic' : 'clinics'} <ArrowUpRightIcon /></span></Link>)}</div></section><section className="home-method"><div className="shell-inner method-grid"><div><Eyebrow>A different kind of directory</Eyebrow><h2>Numbers need a frame.</h2></div><div><p>IVF rates can describe very different things. We keep the denominator, age band, treatment context and source visible — so you can compare what is comparable, and notice what is not.</p><Link href="/methodology" className="text-link" data-testid="link-home-methodology">Read our methodology <ArrowRight size={16} /></Link></div></div></section><section className="home-section shell-inner last-section"><div className="feature-panel"><div><span className="feature-index">01</span><h2>Start with the question, not the score.</h2><p>Look up a clinic, understand its published information, and take useful questions to your appointment.</p><Link href="/clinics" className="btn btn-primary" data-testid="link-browse-clinics">Browse the directory <ArrowRight size={17} /></Link></div><div className="feature-mark"><Stethoscope size={34} /></div></div><Disclaimer /></section></Shell>;
}

function ArrowUpRightIcon() { return <ArrowRight size={14} className="arrow-up-right" />; }

function Clinics() {
  const [location, setLocation] = useLocation();
  const params = new URLSearchParams(location.split('?')[1] || '');
  const [search, setSearch] = useState(params.get('q') || '');
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({ location: params.get('location') || '', service: params.get('service') || '', ageBand: params.get('ageBand') || '', outcomeType: params.get('outcomeType') || '', denominatorType: params.get('denominatorType') || '', eggSource: params.get('eggSource') || '', verificationType: params.get('verificationType') || '', reportingYear: params.get('reportingYear') || '' });
  const apiParams = useMemo(() => ({ q: search || undefined, location: filters.location || undefined, service: filters.service || undefined, ageBand: filters.ageBand || undefined, outcomeType: filters.outcomeType || undefined, denominatorType: filters.denominatorType || undefined, eggSource: filters.eggSource || undefined, verificationType: filters.verificationType || undefined, reportingYear: filters.reportingYear ? Number(filters.reportingYear) : undefined }), [search, filters]);
  const result = useListClinics(apiParams, { query: { queryKey: getListClinicsQueryKey(apiParams) } });
  const data = result.data;
  const update = (key: keyof typeof filters, value: string) => { const next = { ...filters, [key]: value }; setFilters(next); const nextParams = new URLSearchParams(); if (search) nextParams.set('q', search); Object.entries(next).forEach(([k, v]) => v && nextParams.set(k, v)); setLocation(`/clinics${nextParams.toString() ? `?${nextParams}` : ''}`); };
  const submitSearch = (event: React.FormEvent) => { event.preventDefault(); const next = new URLSearchParams(); if (search) next.set('q', search); Object.entries(filters).forEach(([k, v]) => v && next.set(k, v)); setLocation(`/clinics${next.toString() ? `?${next}` : ''}`); };
  return <Shell><PageIntro eyebrow="Public directory" title="Find a clinic with context." description="Search published clinic records and read each observation on its own terms. There is no overall ranking here." /><div className="shell-inner directory-layout"><aside className={`filter-panel ${showFilters ? 'filter-visible' : ''}`}><div className="filter-header"><span className="eyebrow">Refine results</span><button className="close-filter" onClick={() => setShowFilters(false)} data-testid="button-close-filters"><X size={18} /></button></div><label className="field-label">Location<select value={filters.location} onChange={e => update('location', e.target.value)} data-testid="select-filter-location"><option value="">All locations</option>{(data?.availableLocations || []).map((l: Location) => <option value={l.slug} key={l.slug}>{l.city}, {l.state}</option>)}</select></label><label className="field-label">Service<select value={filters.service} onChange={e => update('service', e.target.value)} data-testid="select-filter-service"><option value="">All services</option>{(data?.availableServices || []).map((s: Service) => <option value={s.slug} key={s.slug}>{s.name}</option>)}</select></label><label className="field-label">Age band<select value={filters.ageBand} onChange={e => update('ageBand', e.target.value)} data-testid="select-filter-age"><option value="">Any age band</option><option value="under 35">Under 35</option><option value="35–37">35–37</option><option value="38–40">38–40</option><option value="41–42">41–42</option></select></label><label className="field-label">Outcome type<select value={filters.outcomeType} onChange={e => update('outcomeType', e.target.value)} data-testid="select-filter-outcome"><option value="">Any outcome</option><option value="Live birth">Live birth</option><option value="Clinical pregnancy">Clinical pregnancy</option><option value="Ongoing pregnancy">Ongoing pregnancy</option></select></label><label className="field-label">Denominator<select value={filters.denominatorType} onChange={e => update('denominatorType', e.target.value)} data-testid="select-filter-denominator"><option value="">Any denominator</option><option value="embryo transfers">Embryo transfers</option><option value="started treatment cycles">Started treatment cycles</option></select></label><label className="field-label">Egg source<select value={filters.eggSource} onChange={e => update('eggSource', e.target.value)} data-testid="select-filter-egg-source"><option value="">Any source</option><option value="own eggs">Own eggs</option><option value="donor eggs">Donor eggs</option><option value="donor embryos">Donor embryos</option></select></label><label className="field-label">Verification<select value={filters.verificationType} onChange={e => update('verificationType', e.target.value)} data-testid="select-filter-verification"><option value="">Any verification</option><option value="source-reviewed">Source reviewed</option><option value="independently-verified">Independently verified</option></select></label><label className="field-label">Reporting year<select value={filters.reportingYear} onChange={e => update('reportingYear', e.target.value)} data-testid="select-filter-year"><option value="">Any year</option><option value="2025">2025</option><option value="2024">2024</option></select></label><button className="clear-filters" onClick={() => { setFilters({ location: '', service: '', ageBand: '', outcomeType: '', denominatorType: '', eggSource: '', verificationType: '', reportingYear: '' }); setLocation(search ? `/clinics?q=${encodeURIComponent(search)}` : '/clinics'); }} data-testid="button-clear-filters">Clear all filters</button></aside><div className="directory-results"><div className="directory-toolbar"><form className="directory-search" onSubmit={submitSearch}><Search size={18} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Clinic, city or state" aria-label="Search directory" data-testid="input-directory-search" /><button type="submit" data-testid="button-directory-search"><ArrowRight size={17} /></button></form><Button variant="outline" className="filter-button" onClick={() => setShowFilters(true)} data-testid="button-show-filters"><SlidersHorizontal size={17} /> Filters</Button></div><div className="results-meta"><span data-testid="text-results-count">{data ? `${data.total} ${data.total === 1 ? 'clinic' : 'clinics'}` : 'Clinics'}</span>{Object.values(filters).some(Boolean) && <span className="active-filter-note">Filtered results <button onClick={() => { setFilters({ location: '', service: '', ageBand: '', outcomeType: '', denominatorType: '', eggSource: '', verificationType: '', reportingYear: '' }); setLocation('/clinics'); }} data-testid="button-reset-active-filter">Reset</button></span>}</div>{result.isLoading ? <LoadingBlock lines={5} /> : result.isError ? <ErrorBlock retry={() => result.refetch()} /> : data?.items.length ? <div className="clinic-list">{data.items.map((clinic: Clinic) => <ClinicCard clinic={clinic} key={clinic.id} />)}</div> : <EmptyBlock title="No clinics match those filters." body="Try a broader location or remove one of the filters." />}</div></div><div className="shell-inner directory-disclaimer"><Disclaimer compact /></div></Shell>;
}

function ClinicProfilePage() {
  const { slug = '' } = useParams<{ slug: string }>();
  const profile = useGetClinic(slug, { query: { queryKey: getGetClinicQueryKey(slug) } });
  const clinic = profile.data as ClinicProfile | undefined;
  if (profile.isLoading) return <Shell><div className="shell-inner"><LoadingBlock lines={6} /></div></Shell>;
  if (profile.isError || !clinic) return <Shell><div className="shell-inner"><ErrorBlock retry={() => profile.refetch()} /></div></Shell>;
  return <Shell><div className="shell-inner profile-page"><Link href="/clinics" className="back-link" data-testid="link-back-clinics"><ChevronLeft size={16} />All clinics</Link><div className="profile-heading"><div><Eyebrow>{clinic.city}, {clinic.state}</Eyebrow><h1>{clinic.name}</h1><p className="profile-address">{clinic.address || 'Address not published'} </p></div><div className="profile-stamp"><Check size={15} />Record reviewed<br /><strong>{new Date(clinic.lastReviewedAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}</strong></div></div><div className="profile-grid"><div className="profile-main"><section className="profile-section observation-section"><div className="section-heading"><div><Eyebrow>Published observations</Eyebrow><h2>Read the rate in full.</h2></div><span className="section-count">{clinic.observations.length} {clinic.observations.length === 1 ? 'observation' : 'observations'}</span></div>{clinic.observations.length ? clinic.observations.map(o => <RateDefinition observation={o} expanded key={o.id} />) : <EmptyBlock title="No observations published yet." body="The absence of a published observation is not a statement about a clinic's outcomes." />}</section><section className="profile-section"><Eyebrow>Clinic details</Eyebrow><h2>Services and oversight</h2><div className="detail-columns"><div><span className="detail-label">Services</span><div className="service-pills">{clinic.services.map(service => <span key={service.id}>{service.name}</span>)}</div></div><div><span className="detail-label">Regulator</span><p className="detail-value"><Landmark size={16} />{clinic.regulator || 'Not published'}</p><span className="detail-label">Licensing status</span><p className="detail-value"><ShieldCheck size={16} />{clinic.licensingStatus || 'Not published'}</p></div></div></section><section className="profile-section sources-section"><div className="section-heading"><div><Eyebrow>Sources</Eyebrow><h2>Where this information comes from.</h2></div></div>{clinic.observations.map(o => <div className="source-row" key={o.source.id}><FileText size={17} /><div><strong>{o.source.title}</strong><p>{o.source.publisher || o.source.sourceType}{o.source.publishedOn ? ` · ${o.source.publishedOn}` : ''}</p></div>{o.source.url && <a href={o.source.url} target="_blank" rel="noreferrer" className="icon-link" data-testid={`link-source-${o.source.id}`}><ExternalLink size={16} /></a>}</div>)}</section></div><aside className="profile-sidebar"><div className="contact-card"><Eyebrow>Contact and visit</Eyebrow><h3>Continue your research directly.</h3>{clinic.phone && <a href={`tel:${clinic.phone}`} className="contact-row" data-testid="link-clinic-phone"><Phone size={16} />{clinic.phone}</a>}{clinic.email && <a href={`mailto:${clinic.email}`} className="contact-row" data-testid="link-clinic-email"><Mail size={16} />{clinic.email}</a>}{clinic.website && <a href={clinic.website} target="_blank" rel="noreferrer" className="contact-row" data-testid="link-clinic-website"><LinkIcon size={16} />Clinic website <ExternalLink size={13} /></a>}<div className="contact-rule" /><Link href={`/corrections?clinic=${clinic.slug}`} className="text-link" data-testid="link-profile-correction">Suggest a correction <ArrowRight size={16} /></Link></div><Disclaimer compact /></aside></div></div></Shell>;
}

function Locations() {
  const locations = useListLocations({ query: { queryKey: getListLocationsQueryKey() } });
  return <Shell><PageIntro eyebrow="Browse by place" title="Care, mapped by city." description="A starting point for comparing clinics in the places people travel to for treatment." /><div className="shell-inner locations-page">{locations.isLoading ? <LoadingBlock lines={4} /> : locations.isError ? <ErrorBlock retry={() => locations.refetch()} /> : locations.data?.length ? <div className="location-directory">{locations.data.map((location: Location, index) => <Link key={location.slug} href={`/clinics?location=${location.slug}`} className="location-row" data-testid={`link-location-${location.slug}`}><span className="location-index">{String(index + 1).padStart(2, '0')}</span><span><strong>{location.city}</strong><small>{location.state}</small></span><span className="location-count">{location.clinicCount} {location.clinicCount === 1 ? 'clinic' : 'clinics'}</span><ArrowRight size={18} /></Link>)}</div> : <EmptyBlock title="No locations published yet." body="Check back as the public directory grows." />}</div></Shell>;
}

const glossary = [
  ['Denominator', 'The group of people or treatment cycles that a rate is calculated from. A rate without its denominator is hard to interpret.'],
  ['Embryo transfer', 'A treatment step in which one or more embryos are placed in the uterus. Rates per transfer only describe cycles that reached this step.'],
  ['Live birth rate', 'The proportion of the stated denominator that resulted in a live birth, as defined by the reporting source.'],
  ['Own eggs', 'Eggs retrieved from the person receiving treatment, rather than donor eggs.'],
  ['Cumulative rate', 'A rate that combines outcomes across more than one transfer or treatment step. The source’s method matters.'],
  ['Small sample', 'A note that the denominator is limited. Small numbers can make a percentage more sensitive to a single outcome.'],
];

function Methodology() {
  return <Shell><PageIntro eyebrow="How to read this directory" title="A rate is only useful with its frame." description="We show the information around an IVF observation so that comparison starts with like-for-like questions, not a leaderboard." /><div className="shell-inner reading-layout"><article className="reading-copy"><section><h2>What we keep together</h2><p>Every published observation is displayed with its outcome definition, denominator, age band, egg source, treatment context, reporting period and original source. These are not footnotes; they are the meaning of the number.</p><div className="method-list"><div><span>01</span><strong>Outcome</strong><p>What happened, and how did the source define it?</p></div><div><span>02</span><strong>Denominator</strong><p>Who or what is being counted?</p></div><div><span>03</span><strong>Context</strong><p>Which age, egg source and treatment type?</p></div><div><span>04</span><strong>Time</strong><p>Which reporting period does this represent?</p></div></div></section><section><h2>Comparability is a question, not a score.</h2><p>Two percentages can look similar while describing different populations. We do not combine observations into a clinic score, sort clinics by outcomes, or use performance colors. Instead, each observation carries a comparability group and its source-defined context.</p><p>Where sample sizes are limited, we say so. Where a source does not provide a field, we leave it visible as unavailable rather than filling the gap.</p></section><section><h2>How the directory is maintained</h2><p>Public records are reviewed, attributed and dated. Demonstration records are clearly marked. If you notice an error or a clinic’s information has changed, <Link href="/corrections" className="inline-link" data-testid="link-method-correction">send us a correction</Link> with a source where possible.</p></section></article><aside className="reading-aside"><div className="aside-note"><Sparkles size={18} /><p><strong>A useful habit</strong> Before comparing a percentage, say the full sentence: “X out of Y, for whom, during which period, measured how?”</p></div><div className="aside-links"><p className="eyebrow">Continue reading</p><Link href="/glossary" data-testid="link-method-glossary">Glossary <ArrowRight size={15} /></Link><Link href="/about" data-testid="link-method-about">Project scope <ArrowRight size={15} /></Link></div></aside></div><div className="shell-inner"><Disclaimer /></div></Shell>;
}

function Glossary() {
  return <Shell><PageIntro eyebrow="Plain-language guide" title="The words around the number." description="A short glossary for the terms you will see in clinic records and rate observations." /><div className="shell-inner glossary-grid">{glossary.map(([term, definition], index) => <article className="glossary-item" key={term}><span>{String(index + 1).padStart(2, '0')}</span><h2>{term}</h2><p>{definition}</p></article>)}</div><div className="shell-inner glossary-foot"><Link href="/methodology" className="btn btn-primary" data-testid="link-glossary-methodology">Read the methodology <ArrowRight size={17} /></Link></div></Shell>;
}

function About() {
  return <Shell><PageIntro eyebrow="About clearcare" title="A reference, not a recommendation." description="clearcare is a demonstration public directory designed to make IVF clinic information easier to inspect in India." /><div className="shell-inner reading-layout about-layout"><article className="reading-copy"><section><h2>What this project is for</h2><p>Choosing where to seek care is personal, expensive and often information-heavy. This project gives people a calm place to begin: browse clinic records, see what is published, and understand the shape of each observation before taking questions to a care team.</p></section><section><h2>What it does not do</h2><p>It does not rank clinics, predict an individual’s outcome, verify a treatment plan, or replace advice from a qualified clinician. A missing field is not a negative finding. A rate is not a promise.</p></section><section><h2>Demonstration data</h2><p>This directory currently contains fictional demonstration records to show how a public reference might work. They are not real clinic claims, and should not be used to make healthcare decisions.</p></section></article><aside className="about-rail"><div className="about-quote">“Clarity is not certainty. It is knowing what you are looking at.”</div><div className="about-list"><span>Project type</span><strong>Public reference prototype</strong><span>Geography</span><strong>India</strong><span>Data posture</span><strong>Context before comparison</strong></div></aside></div><div className="shell-inner"><Disclaimer /></div></Shell>;
}

function Corrections() {
  const [location] = useLocation();
  const params = new URLSearchParams(location.split('?')[1] || '');
  const [form, setForm] = useState({ clinicSlug: params.get('clinic') || '', observationId: '', message: '', contactEmail: '' });
  const [done, setDone] = useState(false);
  const submitCorrection = useSubmitCorrection();
  const submit = (event: React.FormEvent) => { event.preventDefault(); submitCorrection.mutate({ data: { ...form, observationId: form.observationId || null } }, { onSuccess: () => setDone(true) }); };
  return <Shell><PageIntro eyebrow="Keep the record useful" title="Notice something that needs correcting?" description="Tell us what looks out of date or inaccurate. Specific, sourced notes help us review changes carefully." /><div className="shell-inner form-layout">{done ? <div className="success-panel"><div className="success-icon"><Check size={22} /></div><Eyebrow>Correction received</Eyebrow><h2>Thank you for helping keep the record clear.</h2><p>Your note has been logged for review. We will use the contact details only if we need to clarify the report.</p><Link href="/clinics" className="btn btn-primary" data-testid="link-correction-directory">Return to directory <ArrowRight size={17} /></Link></div> : <form className="public-form" onSubmit={submit}><label className="field-label">Clinic slug<input required value={form.clinicSlug} onChange={e => setForm({ ...form, clinicSlug: e.target.value })} placeholder="For example, lotus-fertility-delhi" data-testid="input-correction-clinic" /></label><label className="field-label">Observation ID <span className="optional">optional</span><input value={form.observationId} onChange={e => setForm({ ...form, observationId: e.target.value })} placeholder="If your note concerns a specific rate" data-testid="input-correction-observation" /></label><label className="field-label">What should we review?<textarea required minLength={10} maxLength={5000} value={form.message} onChange={e => setForm({ ...form, message: e.target.value })} placeholder="Describe the issue and include a source link if you have one." data-testid="textarea-correction-message" /></label><label className="field-label">Your email<input required type="email" value={form.contactEmail} onChange={e => setForm({ ...form, contactEmail: e.target.value })} placeholder="you@example.com" data-testid="input-correction-email" /></label><Button type="submit" className="submit-button" disabled={submitCorrection.isPending} data-testid="button-submit-correction">{submitCorrection.isPending ? 'Sending…' : 'Send correction'} <ArrowRight size={17} /></Button>{submitCorrection.isError && <p className="form-error">We could not send that just now. Please try again.</p>}<p className="form-footnote">Please do not include medical records or sensitive personal health information.</p></form>}<aside className="form-aside"><div className="aside-note"><ClipboardCheck size={18} /><p><strong>What helps most</strong> The clinic name, the field that needs review, a clear explanation, and a public source or date.</p></div><Link href="/methodology" className="text-link" data-testid="link-correction-methodology">How records are reviewed <ArrowRight size={15} /></Link></aside></div></Shell>;
}

function Privacy() {
  return <Shell><PageIntro eyebrow="Privacy principles" title="Less data, more care." description="The directory should be useful without asking for more than it needs." /><div className="shell-inner legal-copy"><h2>Our approach</h2><p>This demonstration interface is designed around data minimisation. Public browsing does not require an account. We do not ask for health information to search clinics.</p><h2>Correction messages</h2><p>If you submit a correction, we receive the clinic reference, your message and contact email. We use these details to review the note and follow up when needed. Please do not include medical records or sensitive personal health information.</p><h2>Cookies and analytics</h2><p>This prototype does not describe a commercial advertising profile. Any operational logging should be limited to keeping the service secure and functioning.</p><h2>Questions</h2><p>For a privacy question about this demonstration, use the correction channel and identify it as a privacy question.</p></div></Shell>;
}

function Terms() {
  return <Shell><PageIntro eyebrow="Terms" title="Use the directory thoughtfully." description="A few plain-language boundaries for using this public reference." /><div className="shell-inner legal-copy"><h2>Information only</h2><p>clearcare provides general information for research and orientation. It is not medical advice, diagnosis, treatment, referral, or a guarantee of outcomes.</p><h2>Sources and demonstration records</h2><p>Records are presented with their sources and review dates where available. Some records are fictional demonstration data. You are responsible for checking details with the clinic and a qualified clinician before making decisions.</p><h2>Respectful corrections</h2><p>Use the correction form for specific, good-faith reports. Do not submit private health information, abusive content or unrelated marketing.</p><h2>Availability</h2><p>We may change, pause or remove parts of the directory as the project develops. A clinic’s inclusion is not an endorsement.</p></div></Shell>;
}

function Admin() {
  const qc = useQueryClient();
  const summary = useGetAdminSummary({ query: { queryKey: getGetAdminSummaryQueryKey() } });
  const clinics = useListAdminClinics({ query: { queryKey: getListAdminClinicsQueryKey() } });
  const services = useListServices({ query: { queryKey: getListServicesQueryKey() } });
  const sources = useListSources({ query: { queryKey: getListSourcesQueryKey() } });
  const observations = useListRateObservations({ query: { queryKey: getListRateObservationsQueryKey() } });
  const audits = useListAuditEvents({ query: { queryKey: getListAuditEventsQueryKey() } });
  const createClinic = useCreateClinic();
  const updateClinic = useUpdateClinic();
  const archiveClinic = useArchiveClinic();
  const createService = useCreateService();
  const createSource = useCreateSource();
  const createObservation = useCreateRateObservation();
  const publishObservation = usePublishRateObservation();
  const unpublishObservation = useUnpublishRateObservation();
  const previewImport = usePreviewImport();
  const [tab, setTab] = useState('overview');
  const [showClinicForm, setShowClinicForm] = useState(false);
  const [editing, setEditing] = useState<any>(null);
  const [clinicForm, setClinicForm] = useState({ name: '', slug: '', city: '', state: '', address: '', regulator: '', licensingStatus: '', phone: '', email: '', website: '' });
  const [serviceName, setServiceName] = useState('');
  const [sourceForm, setSourceForm] = useState({ title: '', sourceType: 'Registry', url: '', publisher: '', publishedOn: '', notes: '' });
  const [csvText, setCsvText] = useState('');
  const saveClinic = (event: React.FormEvent) => { event.preventDefault(); const data = { ...clinicForm, address: clinicForm.address || null, regulator: clinicForm.regulator || null, licensingStatus: clinicForm.licensingStatus || null, phone: clinicForm.phone || null, email: clinicForm.email || null, website: clinicForm.website || null }; const onSuccess = () => { setShowClinicForm(false); setEditing(null); qc.invalidateQueries({ queryKey: getListAdminClinicsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminSummaryQueryKey() }); }; editing ? updateClinic.mutate({ id: editing.id, data }, { onSuccess }) : createClinic.mutate({ data }, { onSuccess }); };
  const addService = () => { if (!serviceName.trim()) return; createService.mutate({ data: { name: serviceName, slug: serviceName.toLowerCase().trim().replaceAll(/\s+/g, '-'), description: null } }, { onSuccess: () => { setServiceName(''); qc.invalidateQueries({ queryKey: getListServicesQueryKey() }); } }); };
  const addSource = (event: React.FormEvent) => { event.preventDefault(); createSource.mutate({ data: { ...sourceForm, publisher: sourceForm.publisher || null, publishedOn: sourceForm.publishedOn || null, notes: sourceForm.notes || null } }, { onSuccess: () => { setSourceForm({ title: '', sourceType: 'Registry', url: '', publisher: '', publishedOn: '', notes: '' }); qc.invalidateQueries({ queryKey: getListSourcesQueryKey() }); } }); };
  const isBusy = summary.isLoading || clinics.isLoading;
  return <Shell><div className="admin-shell"><div className="shell-inner admin-head"><div><Eyebrow>Protected workspace</Eyebrow><h1>Directory desk</h1><p>Review records, publish carefully, keep an audit trail.</p></div><div className="admin-lock"><ShieldCheck size={17} />Editor surface</div></div><div className="shell-inner admin-tabs" role="tablist">{['overview', 'clinics', 'observations', 'sources', 'import', 'audit'].map(item => <button key={item} onClick={() => setTab(item)} className={tab === item ? 'active' : ''} role="tab" data-testid={`tab-admin-${item}`}>{item}</button>)}</div><div className="shell-inner admin-content">{isBusy ? <LoadingBlock lines={5} /> : summary.isError ? <div className="state-card"><p className="eyebrow">Authentication setup required</p><h2>Editor access is not configured.</h2><p>This protected workspace is intentionally unavailable until managed administrator authentication is connected. Public clinic browsing remains available without an account.</p><Link href="/about" className="text-link">Read the project scope <ArrowRight size={15} /></Link></div> : tab === 'overview' ? <><div className="metric-grid"><div><span>Clinic records</span><strong>{summary.data?.clinicCount ?? 0}</strong><small>All statuses</small></div><div><span>Published observations</span><strong>{summary.data?.publishedObservationCount ?? 0}</strong><small>Visible publicly</small></div><div><span>Draft observations</span><strong>{summary.data?.draftObservationCount ?? 0}</strong><small>Awaiting review</small></div><div><span>Corrections pending</span><strong>{summary.data?.pendingCorrectionCount ?? 0}</strong><small>Need attention</small></div></div><section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Recent activity</Eyebrow><h2>Audit trail</h2></div><button className="text-link-button" onClick={() => setTab('audit')} data-testid="button-view-audit">View all <ArrowRight size={15} /></button></div>{summary.data?.recentAuditEvents?.length ? summary.data.recentAuditEvents.slice(0, 6).map(event => <div className="audit-row" key={event.id}><span className="audit-action">{event.action}</span><span>{event.entityType} · {event.entityId}</span><time>{new Date(event.createdAt).toLocaleDateString('en-IN')}</time></div>) : <EmptyBlock title="No recent activity." body="Changes will appear here as records move through review." />}</section></> : tab === 'clinics' ? <section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Records workflow</Eyebrow><h2>Clinics</h2></div><Button onClick={() => { setEditing(null); setClinicForm({ name: '', slug: '', city: '', state: '', address: '', regulator: '', licensingStatus: '', phone: '', email: '', website: '' }); setShowClinicForm(true); }} data-testid="button-add-clinic"><Plus size={16} /> Add clinic</Button></div>{showClinicForm && <form className="admin-form" onSubmit={saveClinic}><div className="form-grid">{(['name', 'slug', 'city', 'state', 'address', 'regulator', 'licensingStatus', 'phone', 'email', 'website'] as const).map(field => <label className="field-label" key={field}>{field}<input required={['name', 'slug', 'city', 'state'].includes(field)} value={clinicForm[field]} onChange={e => setClinicForm({ ...clinicForm, [field]: e.target.value })} data-testid={`input-admin-clinic-${field}`} /></label>)}</div><div className="form-actions"><Button type="submit" disabled={createClinic.isPending || updateClinic.isPending} data-testid="button-save-clinic">{editing ? 'Save changes' : 'Create draft'}</Button><Button type="button" variant="quiet" onClick={() => setShowClinicForm(false)} data-testid="button-cancel-clinic">Cancel</Button></div></form>}{clinics.data?.map((clinic: any) => <div className="admin-record-row" key={clinic.id}><div><strong>{clinic.name}</strong><span>{clinic.city}, {clinic.state} · {clinic.recordStatus}</span></div><div className="row-actions"><button className="icon-text-button" onClick={() => { setEditing(clinic); setClinicForm({ name: clinic.name, slug: clinic.slug, city: clinic.city, state: clinic.state, address: clinic.address || '', regulator: clinic.regulator || '', licensingStatus: clinic.licensingStatus || '', phone: clinic.phone || '', email: clinic.email || '', website: clinic.website || '' }); setShowClinicForm(true); }} data-testid={`button-edit-clinic-${clinic.id}`}>Edit</button><button className="icon-text-button danger-text" onClick={() => { if (window.confirm('Archive this clinic record?')) archiveClinic.mutate({ id: clinic.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAdminClinicsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminSummaryQueryKey() }); } }); }} data-testid={`button-archive-clinic-${clinic.id}`}>Archive</button></div></div>)}</section> : tab === 'observations' ? <section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Rate records</Eyebrow><h2>Observation queue</h2></div><span className="panel-count">{observations.data?.length || 0} records</span></div>{observations.data?.map((observation: RateObservation) => <div className="admin-record-row" key={observation.id}><div><strong>{observation.outcomeType} · {observation.yearLabel}</strong><span>{observation.outcomeDefinition} · {observation.publicationStatus}</span></div><div className="row-actions">{observation.publicationStatus === 'published' ? <button className="icon-text-button" onClick={() => unpublishObservation.mutate({ id: observation.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListRateObservationsQueryKey() }) })} data-testid={`button-unpublish-${observation.id}`}>Unpublish</button> : <button className="icon-text-button" onClick={() => publishObservation.mutate({ id: observation.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListRateObservationsQueryKey() }); qc.invalidateQueries({ queryKey: getGetAdminSummaryQueryKey() }); } })} data-testid={`button-publish-${observation.id}`}>Publish</button>}</div></div>)}</section> : tab === 'sources' ? <section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Evidence library</Eyebrow><h2>Sources and services</h2></div></div><form className="admin-form" onSubmit={addSource}><div className="form-grid">{(['title', 'sourceType', 'url', 'publisher', 'publishedOn'] as const).map(field => <label className="field-label" key={field}>{field}<input required={['title', 'sourceType', 'url'].includes(field)} value={sourceForm[field]} onChange={e => setSourceForm({ ...sourceForm, [field]: e.target.value })} data-testid={`input-admin-source-${field}`} /></label>)}</div><label className="field-label">notes<textarea value={sourceForm.notes} onChange={e => setSourceForm({ ...sourceForm, notes: e.target.value })} data-testid="textarea-admin-source-notes" /></label><Button type="submit" disabled={createSource.isPending} data-testid="button-create-source"><Plus size={16} /> Add source</Button></form><div className="admin-subsection"><p className="eyebrow">Services</p><div className="service-add"><input value={serviceName} onChange={e => setServiceName(e.target.value)} placeholder="New service name" data-testid="input-admin-service-name" /><Button onClick={addService} disabled={createService.isPending} data-testid="button-create-service">Add</Button></div>{services.data?.map((service: Service) => <div className="small-record" key={service.id}><span>{service.name}</span><code>{service.slug}</code></div>)}</div><div className="admin-subsection"><p className="eyebrow">Sources</p>{sources.data?.map((source: any) => <div className="small-record" key={source.id}><span>{source.title}</span><code>{source.sourceType}</code></div>)}</div></section> : tab === 'import' ? <ImportPanel csvText={csvText} setCsvText={setCsvText} previewImport={previewImport} /> : <section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Immutable history</Eyebrow><h2>Audit events</h2></div></div>{audits.data?.map(event => <div className="audit-row" key={event.id}><span className="audit-action">{event.action}</span><span>{event.entityType} · {event.entityId}</span><time>{new Date(event.createdAt).toLocaleString('en-IN')}</time></div>)}</section>}</div></div></Shell>;
}

function ImportPanel({ csvText, setCsvText, previewImport }: { csvText: string; setCsvText: (value: string) => void; previewImport: ReturnType<typeof usePreviewImport> }) {
  const [preview, setPreview] = useState<any>(null);
  const runPreview = () => previewImport.mutate({ data: { csvText, mapping: {} } }, { onSuccess: setPreview });
  return <section className="admin-panel"><div className="panel-heading"><div><Eyebrow>Validation only</Eyebrow><h2>Preview a CSV import</h2></div></div><p className="panel-copy">Paste CSV text to validate rows before anything is written. This step does not create records.</p><textarea className="csv-input" value={csvText} onChange={e => setCsvText(e.target.value)} placeholder="clinic_name,city,state&#10;Example Clinic,Delhi,Delhi" data-testid="textarea-import-csv" /><Button onClick={runPreview} disabled={!csvText.trim() || previewImport.isPending} data-testid="button-preview-import">{previewImport.isPending ? 'Checking…' : 'Check rows'} <ArrowRight size={16} /></Button>{preview && <div className="import-result"><div><strong>{preview.validRows}</strong><span>valid rows</span></div><div><strong>{preview.invalidRows}</strong><span>invalid rows</span></div><div><strong>{preview.duplicateRows}</strong><span>duplicates</span></div>{preview.errors?.length > 0 && <div className="import-errors">{preview.errors.map((error: any) => <p key={`${error.rowNumber}-${error.field}`}>Row {error.rowNumber} · {error.field}: {error.message}</p>)}</div>}</div>}</section>;
}

function AppRouter() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={Home} /><Route path="/clinics" component={Clinics} /><Route path="/clinics/:slug" component={ClinicProfilePage} /><Route path="/locations" component={Locations} /><Route path="/methodology" component={Methodology} /><Route path="/glossary" component={Glossary} /><Route path="/about" component={About} /><Route path="/privacy" component={Privacy} /><Route path="/terms" component={Terms} /><Route path="/corrections" component={Corrections} /><Route path="/admin" component={Admin} /><Route path="/not-found" component={NotFound} /><Route component={NotFound} /></Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;